PROJECT="paper"; USER_AGENT="MyServer/1.0 (contact@example.com)"; STABLE_URL=$(curl -s -H "User-Agent: $USER_AGENT" "https://fill.papermc.io/v3/projects/${PROJECT}" | jq -r ".versions | to_entries[0].value[0]" | xargs -I {} curl -s -H "User-Agent: $USER_AGENT" "https://fill.papermc.io/v3/projects/${PROJECT}/versions/{}/builds" | jq -r "map(select(.channel == \"STABLE\"))[0].downloads.\"server:default\".url"); curl -H "User-Agent: $USER_AGENT" -L -o paper.jar "$STABLE_URL"
